import { Controller, Get, type INestApplication, Post } from '@nestjs/common';
import { apiErrorBodySchema, appConfigSchema, ErrorCode } from '@artifact-hub/shared';
import request from 'supertest';
import { z } from 'zod';
import { Public } from '../src/auth/auth.decorators.js';
import { AppError } from '../src/common/errors/app-error.js';
import { GENERIC_ERROR_MESSAGE } from '../src/common/errors/error-response.js';
import { createTestApp } from './create-test-app.js';
import { testEnv } from './test-env.js';

@Public()
@Controller('test-errors')
class ErrorsTestController {
  @Get('domain')
  domain() {
    throw new AppError(ErrorCode.CONFLICT, 'Already exists', { field: 'title' });
  }

  @Get('validation')
  validation() {
    z.object({ title: z.string().min(1) }).parse({ title: '' });
  }

  @Get('crash')
  crash() {
    throw new Error('secret internals');
  }

  @Post('echo')
  echo() {
    return { ok: true };
  }
}

describe('App (e2e)', () => {
  let app: INestApplication;

  beforeAll(async () => {
    app = await createTestApp({ controllers: [ErrorsTestController] });
  });

  afterAll(async () => {
    await app.close();
  });

  async function expectError(path: string, status: number, code: ErrorCode) {
    const res = await request(app.getHttpServer())
      .get(path)
      .set('X-Request-Id', 'req-1')
      .expect(status);
    const body = apiErrorBodySchema.parse(res.body);
    expect(body.error.code).toBe(code);
    expect(body.error.requestId).toBe('req-1');
    return body.error;
  }

  describe('GET /api/health', () => {
    it('returns ok with a generated request id', async () => {
      const res = await request(app.getHttpServer()).get('/api/health').expect(200);
      expect(res.body).toEqual({ status: 'ok', checks: { database: 'up', storage: 'up' } });
      expect(res.headers['x-request-id']).toMatch(/^[0-9a-f-]{36}$/);
    });

    it('echoes a well-formed incoming request id', async () => {
      const res = await request(app.getHttpServer())
        .get('/api/health')
        .set('X-Request-Id', 'client-trace-42')
        .expect(200);
      expect(res.headers['x-request-id']).toBe('client-trace-42');
    });
  });

  describe('GET /api/config', () => {
    it('returns the client configuration without a session', async () => {
      const res = await request(app.getHttpServer()).get('/api/config').expect(200);
      expect(appConfigSchema.parse(res.body)).toEqual({
        maxArtifactBytes: testEnv.MAX_ARTIFACT_BYTES,
      });
    });
  });
# Enhancements Backlog

Known limitations of the current build, and planned improvements.

## Identity and access

### SSO + verified identities (high priority)

**Current state:** Signup takes an email + password without verification. Sharing with specific users only checks that an account with that email exists.

**Risk:** Anyone can register with someone else's email (e.g. `bob@corp.com`) before Bob does, and then receive anything shared with that address.

**Planned:**
- Add SSO (OIDC — e.g. Google Workspace / Microsoft Entra ID) as the primary login, so emails are verified by the identity provider.
- Restrict signup to company domains; disable password signup once SSO is live (or require email verification for it).
- Allow sharing with emails that are not registered yet: create a pending grant that is attached to the account on first SSO login. Schema change: add a separate `share_invites(artifact_id, email, permission, pinned_version_id)` table, converted into `shares` rows on first login. `shares` itself keeps a strict `user_id` foreign key.
- Add group/team-based sharing synced from the identity provider.

### Sharing
- Several named links per artifact (e.g. one per client), each with its own expiry and version, revocable separately. One link per artifact covers the common case for now.
- Expiry for people and for company access (today only the link expires).
- Comments from link visitors, with a guest name and spam protection.
- Notify people when something is shared with them (see Platform).

### Password lifecycle
- Password reset via email, password change, and session management UI ("log out other devices").

### Rate limiting
**Current state:** `@nestjs/throttler` with its default in-memory store limits login attempts per client IP and per email (and signups per IP), over a fixed window. Every attempt counts, successful or not.

**Limitations:**
- Counters live in the process: they reset on restart and are not shared between replicas.
- Memory grows with the number of distinct keys (IPs, emails) seen in a window, so a flood of requests with random emails can inflate it until the window expires.
- Anyone can use up the per-email budget of someone else's account and temporarily lock them out.

**Planned:**
- Move counters to Redis (e.g. `@nest-lab/throttler-storage-redis`): every key gets a TTL equal to its window (`INCR` + `PEXPIRE`), so memory stays bounded and expired entries clean themselves up. Counters are then shared across replicas and survive restarts.
- Cap the in-memory store's size in the meantime (LRU), as a fallback when Redis is not configured.
- Count only failed logins per email, reset the counter after a successful login, and use exponential backoff instead of a hard block, so a targeted lockout is short-lived.

## Storage and content
- Implement the `s3` and `azure` `StorageDriver`s (interfaces already in place), with optional presigned download URLs.
- Serve user content from a separate domain (`usercontent.<domain>`) as defense in depth beyond the CSP sandbox.
- Multi-file HTML bundles (zip upload with asset rewriting).
- Server-generated thumbnails.

## Platform
- Horizontal scaling (requires object storage instead of a local volume, and a real job queue).
- Notifications (email/Slack) for new comments, shares and new versions.
- Positional annotations on artifacts (the `comments.anchor` column is reserved for this).
- Activity feed and persisted audit log (`activity_events` table) once there is collaborative editing, notifications or compliance needs. For now, versions, comments and share timestamps plus structured logs cover this.
import { z } from 'zod';
import type { Env } from './config.types.js';

// Development defaults match docker-compose.yml, so `pnpm dev` works without a .env file.
const DEV_APP_BASE_URL = 'http://localhost:5173';
const DEV_DATABASE_URL = 'postgres://artifact_hub:artifact_hub@localhost:5432/artifact_hub';
/** Relative to the API's working directory (`apps/api`), which git and Docker ignore. */
const DEV_STORAGE_LOCAL_ROOT = '.data/blobs';
/** A fixed key so links survive restarts in development and tests. Never used in production. */
const DEV_SHARE_LINK_KEY = Buffer.from('dev-only-share-link-key-32-bytes').toString('base64');

const SHARE_LINK_KEY_BYTES = 32;

export const envSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    PORT: z.coerce.number().int().min(1).max(65535).default(3000),
    /** Public origin of the web app; used for links (share URLs, upload URLs) and the CSRF Origin check. */
    APP_BASE_URL: z.url({ protocol: /^https?$/ }).optional(),
    LOG_LEVEL: z
      .enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace', 'silent'])
      .default('info'),
    DATABASE_URL: z.url({ protocol: /^postgres(ql)?$/ }).optional(),
    /** Directory of the built SPA. When set, the API also serves the web app (production image). */
    WEB_DIST_DIR: z.string().optional(),
    /**
     * Number of reverse proxies in front of the app (1 on Railway). Needed so the client IP used
     * for rate limiting and session records is the real one, not the proxy's.
     */
    TRUST_PROXY_HOPS: z.coerce.number().int().min(0).max(10).default(0),
    SESSION_TTL_DAYS: z.coerce.number().int().min(1).max(365).default(7),
    /** Defaults to true in production and false otherwise (plain-http dev server). */
    COOKIE_SECURE: z.stringbool().optional(),
    /** Login attempts allowed per window, counted per client IP and per email. */
    RATE_LIMIT_LOGIN_PER_IP: z.coerce.number().int().min(1).default(20),
    RATE_LIMIT_LOGIN_PER_EMAIL: z.coerce.number().int().min(1).default(10),
    RATE_LIMIT_LOGIN_WINDOW_SECONDS: z.coerce.number().int().min(1).default(900),
    RATE_LIMIT_USER_SEARCH_PER_MINUTE: z.coerce.number().int().min(1).default(60),
    /** Requests per client IP to share link pages and their content, which need no sign-in. */
    RATE_LIMIT_SHARE_LINK_PER_MINUTE: z.coerce.number().int().min(1).default(120),
    /**
     * 32 random bytes, base64 (`openssl rand -base64 32`). Encrypts share link tokens so owners
     * can copy their links again; links are looked up by hash, so a database leak alone exposes
     * none. Changing it makes existing links uncopyable (they keep working). Required in
     * production.
     */
    SHARE_LINK_KEY: z
      .string()
      .refine((key) => Buffer.from(key, 'base64').length === SHARE_LINK_KEY_BYTES, {
        message: `Must be ${SHARE_LINK_KEY_BYTES} bytes, base64-encoded`,
      })
      .optional(),
    /** Where artifact content is stored. Only `local` is implemented; s3/azure are planned. */
    STORAGE_DRIVER: z.enum(['local', 's3', 'azure']).default('local'),
    /** Root directory of the `local` driver (a mounted volume in production). */
    STORAGE_LOCAL_ROOT: z.string().optional(),
    /** Largest artifact version accepted, enforced while the upload streams in. 10 MB by default. */
    MAX_ARTIFACT_BYTES: z.coerce
      .number()
      .int()
      .min(1)
      .max(1024 * 1024 * 1024)
      .default(10 * 1024 * 1024),
  })
  .transform((env, ctx) => {
    if (env.NODE_ENV === 'production') {
      for (const key of ['APP_BASE_URL', 'DATABASE_URL', 'SHARE_LINK_KEY'] as const) {
        if (!env[key])
          ctx.addIssue({ code: 'custom', path: [key], message: 'Required in production' });
      }
      // Never fall back to a directory inside the container, which is lost on redeploy.
      if (env.STORAGE_DRIVER === 'local' && !env.STORAGE_LOCAL_ROOT) {
        ctx.addIssue({
          code: 'custom',
          path: ['STORAGE_LOCAL_ROOT'],
          message: 'Required in production when STORAGE_DRIVER=local',
        });
      }
      if (ctx.issues.length > 0) return z.NEVER;
    }
    return {
      ...env,
      APP_BASE_URL: (env.APP_BASE_URL ?? DEV_APP_BASE_URL).replace(/\/+$/, ''),
      DATABASE_URL: env.DATABASE_URL ?? DEV_DATABASE_URL,
      COOKIE_SECURE: env.COOKIE_SECURE ?? env.NODE_ENV === 'production',
      STORAGE_LOCAL_ROOT: env.STORAGE_LOCAL_ROOT ?? DEV_STORAGE_LOCAL_ROOT,
      SHARE_LINK_KEY: env.SHARE_LINK_KEY ?? DEV_SHARE_LINK_KEY,
    };
  });

export class InvalidEnvError extends Error {
  constructor(error: z.ZodError) {
    super(`Invalid environment configuration:\n${z.prettifyError(error)}`);
    this.name = 'InvalidEnvError';
  }
}

/** Parses and validates environment variables. Throws `InvalidEnvError` listing every problem. */
export function parseEnv(source: Record<string, string | undefined>): Env {
  // Treat empty strings as unset so `FOO=` in a .env file falls back to the default.
  const cleaned = Object.fromEntries(Object.entries(source).filter(([, value]) => value !== ''));
  const result = envSchema.safeParse(cleaned);
  if (!result.success) throw new InvalidEnvError(result.error);
  return result.data;
}

