import { z } from 'zod';
import { artifactVersionSchema } from './artifacts.js';

/** `comment` includes `view`. */
export const SHARE_PERMISSIONS = ['view', 'comment'] as const;
export const sharePermissionSchema = z.enum(SHARE_PERMISSIONS);
export type SharePermission = z.infer<typeof sharePermissionSchema>;

/** The version an access level shows: a version number, or null for always the latest. */
const versionChoiceSchema = z.number().int().positive().nullable();

export const SHARE_PEOPLE_MAX = 20;

/** A colleague with access, as the artifact's owner sees them. */
export const sharedPersonSchema = z.object({
  user: z.object({ id: z.uuid(), displayName: z.string(), email: z.string() }),
  permission: sharePermissionSchema,
  /** The only version they see through this share; null = always the latest. */
  pinnedVersionNo: z.number().int().positive().nullable(),
  sharedAt: z.iso.datetime(),
});

export type SharedPerson = z.infer<typeof sharedPersonSchema>;

/**
 * The artifact's link for people outside the company: anyone who has it can view and download
 * without signing in. Only the owner sees it, and can copy it any time.
 */
export const shareLinkSchema = z.object({
  url: z.url(),
  /** The only version it shows; null = all versions (following the latest). */
  pinnedVersionNo: z.number().int().positive().nullable(),
  /** When it stops working; null = never. May be in the past (expired, not yet turned off). */
  expiresAt: z.iso.datetime().nullable(),
  createdAt: z.iso.datetime(),
});

export type ShareLink = z.infer<typeof shareLinkSchema>;

/** Who has access to an artifact besides its owner. Owner only. */
export const artifactAccessSchema = z.object({
  /** Everyone at the company (signed in) can view and comment. */
  company: z.object({
    enabled: z.boolean(),
    pinnedVersionNo: z.number().int().positive().nullable(),
  }),
  /** In the order they were added. */
  people: z.array(sharedPersonSchema),
  /** Null when there is no link (it was never turned on, or was turned off). */
  link: shareLinkSchema.nullable(),
});

export type ArtifactAccess = z.infer<typeof artifactAccessSchema>;

/** Response of `GET /api/artifacts/:id/access` and of every change to it. */
export const artifactAccessResponseSchema = z.object({ access: artifactAccessSchema });

export type ArtifactAccessResponse = z.infer<typeof artifactAccessResponseSchema>;

/** Body of `PUT /api/artifacts/:id/access/company`. */
export const setCompanyAccessRequestSchema = z.object({
  enabled: z.boolean(),
  versionNo: versionChoiceSchema.default(null),
});

export type SetCompanyAccessRequest = z.input<typeof setCompanyAccessRequestSchema>;
export type SetCompanyAccessOptions = z.output<typeof setCompanyAccessRequestSchema>;

/**
 * Body of `POST /api/artifacts/:id/access/people`. People who already have access get the new
 * permission and version.
 */
export const sharePeopleRequestSchema = z.object({
  emails: z
    .array(z.string().trim().toLowerCase().pipe(z.email('Enter valid email addresses.')))
    .min(1, 'Add at least one email.')
    .max(SHARE_PEOPLE_MAX, `Share with at most ${SHARE_PEOPLE_MAX} people at once.`)
    .transform((emails) => [...new Set(emails)]),
  permission: sharePermissionSchema,
  versionNo: versionChoiceSchema.default(null),
import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Patch,
  Post,
  Put,
} from '@nestjs/common';
import {
  type ArtifactAccessResponse,
  type SetCompanyAccessOptions,
  type SetShareLinkOptions,
  type SharePeopleOptions,
  type UpdatePersonAccessOptions,
  setCompanyAccessRequestSchema,
  setShareLinkRequestSchema,
  sharePeopleRequestSchema,
  updatePersonAccessRequestSchema,
} from '@artifact-hub/shared';
import { CurrentActor } from '../auth/auth.decorators.js';
import type { Actor } from '../auth/auth.types.js';
import { ZodValidationPipe } from '../common/validation/zod-validation.pipe.js';
import { SharingService } from './sharing.service.js';

/** Access settings of an artifact; owner only. Every change returns the settings as they are now. */
@Controller('artifacts/:id/access')
export class SharingController {
  constructor(private readonly sharing: SharingService) {}

  @Get()
  async get(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.getAccess(actor, artifactId) };
  }

  @Put('company')
  async setCompany(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(setCompanyAccessRequestSchema)) options: SetCompanyAccessOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.setCompanyAccess(actor, artifactId, options) };
  }

  /** Answers 422 `SHARE_RECIPIENT_UNKNOWN`, listing them, if any email has no account. */
  @Post('people')
  async sharePeople(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(sharePeopleRequestSchema)) options: SharePeopleOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.sharePeople(actor, artifactId, options) };
  }

  @Patch('people/:userId')
  async updatePerson(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Param('userId') userId: string,
    @Body(new ZodValidationPipe(updatePersonAccessRequestSchema))
    changes: UpdatePersonAccessOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.updatePerson(actor, artifactId, userId, changes) };
  }

  @Delete('people/:userId')
  async removePerson(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Param('userId') userId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.removePerson(actor, artifactId, userId) };
  }

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Patch,
  Post,
  Query,
} from '@nestjs/common';
import {
  type CommentListQuery,
  type CommentListResponse,
  type CommentResponse,
  type CreateCommentOptions,
  type UpdateCommentOptions,
  commentListQuerySchema,
  createCommentRequestSchema,
  updateCommentRequestSchema,
} from '@artifact-hub/shared';
import { CurrentActor } from '../auth/auth.decorators.js';
import type { Actor } from '../auth/auth.types.js';
import { ZodValidationPipe } from '../common/validation/zod-validation.pipe.js';
import { toCommentDto, toCommentThreadDto } from './comment.entity.js';
import { CommentsService } from './comments.service.js';

@Controller()
export class CommentsController {
  constructor(private readonly comments: CommentsService) {}

  /** `?version=N` for one version's threads; `?include=open` leaves out resolved ones. */
  @Get('artifacts/:id/comments')
  async list(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Query(new ZodValidationPipe(commentListQuerySchema)) { version, include }: CommentListQuery,
  ): Promise<CommentListResponse> {
    const threads = await this.comments.list(actor, artifactId, { versionNo: version, include });
    return { items: threads.map(toCommentThreadDto) };
  }

  @Post('artifacts/:id/comments')
  async create(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(createCommentRequestSchema)) options: CreateCommentOptions,
  ): Promise<CommentResponse> {
    return { comment: toCommentDto(await this.comments.create(actor, artifactId, options)) };
  }

  /** Edits the body, or resolves (`resolved: true`) or reopens a top-level comment. */
  @Patch('comments/:id')
  async update(
    @CurrentActor() actor: Actor,
    @Param('id') commentId: string,
    @Body(new ZodValidationPipe(updateCommentRequestSchema)) changes: UpdateCommentOptions,
  ): Promise<CommentResponse> {
    return { comment: toCommentDto(await this.comments.update(actor, commentId, changes)) };

