                setLink.mutate({ expiresAt: link.expiresAt, versionNo }, { onError: toastError })
              }
            />
            <ResetLinkButton
              disabled={busy}
              onConfirm={() =>
                reset.mutate(undefined, {
                  onSuccess: () => toast.success('New link created'),
                  onError: toastError,
                })
              }
            />
          </div>
        </>
      ) : null}
    </div>
  );
}

