import { type CanActivate, type ExecutionContext, Injectable } from '@nestjs/common';
import { ErrorCode } from '@artifact-hub/shared';
import type { Request } from 'express';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import { AppError } from '../common/errors/app-error.js';
import { ApiTokensService } from './api-tokens.service.js';

const BEARER = /^Bearer\s+(\S+)\s*$/i;

/**
 * Authenticates a route with an API token (`Authorization: Bearer ah_…`) instead of a session.
 * Applied with `@BearerAuth()`, never on its own. Sets `req.auth` with an MCP actor.
 */
@Injectable()
export class BearerGuard implements CanActivate {
  constructor(
    private readonly tokens: ApiTokensService,
    @InjectPinoLogger(BearerGuard.name) private readonly logger: PinoLogger,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    if (context.getType() !== 'http') {
      throw new Error(`BearerGuard only supports HTTP, not '${context.getType()}'`);
    }
    const req = context.switchToHttp().getRequest<Request>();
    const secret = BEARER.exec(req.get('authorization') ?? '')?.[1];
    const result = await this.tokens.check(secret);
    if (!result.ok) {
      this.logger.warn(
        { reason: result.reason, tokenId: result.tokenId, ip: req.ip },
        'API token rejected',
      );
      throw new AppError(
        ErrorCode.UNAUTHENTICATED,
        result.reason === 'missing'
          ? 'Send an API token as "Authorization: Bearer <token>". Create one in Settings → API tokens.'
          : 'This API token is not valid or was revoked. Create a new one in Settings → API tokens.',
      );
    }
    const { token } = result;
    req.auth = { actor: { userId: token.userId, via: 'mcp' }, apiTokenId: token.id };
    this.logger.assign({ userId: token.userId, tokenId: token.id });
    return true;
  }
}
