export function GalleryPage() {
  const { page, ...filters } = useGalleryParams();
  const { scope } = filters;
  const navigate = useNavigate();
  const pageSize = ARTIFACT_LIST_DEFAULT_PAGE_SIZE;
  const { data, error, refetch, isPlaceholderData } = useArtifactList({
    ...filters,
    page,
    pageSize,
  });
  const filtered = Boolean(filters.q || filters.type || filters.tag);
  // New filters start from the first page, without piling up history while typing.
  const applyFilters = (next: Filters) => void navigate(galleryHref(next), { replace: true });

  return (
    <section className="grid gap-6">
      <nav aria-label="Gallery" className="flex gap-1 border-b">
        {ARTIFACT_LIST_SCOPES.map((s) => (
          <Link
            key={s}
            to={galleryHref({ scope: s })}
            aria-current={s === scope ? 'page' : undefined}
            className={cn(
              '-mb-px border-b-2 px-3 py-2 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none',
              s === scope
                ? 'border-primary text-foreground'
                : 'border-transparent text-muted-foreground hover:text-foreground',
            )}
          >
            {SCOPES[s].tab}
          </Link>
        ))}
      </nav>

      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h1 className="text-2xl font-semibold tracking-tight">{SCOPES[scope].heading}</h1>
        {isPlaceholderData ? (
          <p role="status" className="flex items-center gap-1.5 text-sm text-muted-foreground">
            <Loader2Icon className="size-4 animate-spin" aria-hidden="true" />
            {filtered ? 'Searching…' : 'Loading…'}
          </p>
        ) : data && data.total > 0 ? (
          <p className="text-sm text-muted-foreground">
            {data.total} {data.total === 1 ? 'artifact' : 'artifacts'}
          </p>
        ) : null}
      </div>

      <GalleryFilters
        key={scope}
        filters={filters}
        loading={isPlaceholderData}
        onChange={applyFilters}
      />

      {error ? (
        <div className="h-64">
          <InlineError error={error} onRetry={() => void refetch()} />
        </div>
      ) : !data ? (
        <div className="h-64">
          <InlineLoading />
        </div>
      ) : data.total === 0 && filtered ? (
        <div className="flex flex-col items-center gap-3 rounded-xl border border-dashed py-16 text-center">
          <h2 className="text-lg font-medium">No artifacts match</h2>
          <p className="max-w-sm text-sm text-muted-foreground">
            Try other words, or fewer filters.
          </p>
          <Button variant="outline" onClick={() => applyFilters({ scope })}>
            Clear filters
          </Button>
        </div>
      ) : data.total === 0 ? (
        <EmptyGallery scope={scope} />
      ) : data.items.length === 0 ? (
        <p className="py-16 text-center text-muted-foreground">
          There's nothing on this page.{' '}
          <Link to={galleryHref(filters)} className="underline">
import type { SharedPerson } from '@artifact-hub/shared';
import { XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button.tsx';
import { toastError } from '@/lib/toast-error.ts';
import { PermissionSelect, VersionSelect } from './access-selects.tsx';
import { useRemovePerson, useUpdatePerson } from './use-sharing.ts';

/** Everyone the artifact is shared with; changes are saved as they are made. */
export function PeopleList({ artifactId, people }: { artifactId: string; people: SharedPerson[] }) {
  const update = useUpdatePerson(artifactId);
  const remove = useRemovePerson(artifactId);

  if (people.length === 0) {
    return <p className="text-sm text-muted-foreground">Not shared with anyone yet.</p>;
  }

  return (
    <ul className="grid gap-1" aria-label="People with access">
      {people.map((person) => {
        const { user } = person;
        const busy =
          (update.isPending && update.variables.userId === user.id) ||
          (remove.isPending && remove.variables === user.id);
        return (
          <li key={user.id} className="flex flex-wrap items-center gap-2 py-1.5 text-sm">
            <span className="grid min-w-0 flex-1 basis-40">
              <span className="truncate font-medium">{user.displayName}</span>
              <span className="truncate text-xs text-muted-foreground">{user.email}</span>
            </span>
            <PermissionSelect
              aria-label={`Permission for ${user.displayName}`}
              value={person.permission}
              disabled={busy}
              onChange={(permission) =>
                update.mutate({ userId: user.id, permission }, { onError: toastError })
              }
            />
            <VersionSelect
              aria-label={`Version for ${user.displayName}`}
              artifactId={artifactId}
              value={person.pinnedVersionNo}
              disabled={busy}
              onChange={(versionNo) =>
                update.mutate({ userId: user.id, versionNo }, { onError: toastError })
              }
            />
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={`Remove ${user.displayName}`}
              disabled={busy}
              onClick={() => remove.mutate(user.id, { onError: toastError })}
            >
              <XIcon aria-hidden="true" />
            </Button>
          </li>
        );
      })}
    </ul>
  );
}

