import type { FieldValues, Path, UseFormSetError } from 'react-hook-form';
import { describeError, isApiError } from '@/lib/api/api-error.ts';

/**
 * Shows a failed submission on the form: validation issues next to their fields, everything
 * else as a form-level message (`errors.root.server`). An issue on a nested path (`tags.0`)
 * goes to the field it belongs to (`tags`).
 */
export function applyServerError<T extends FieldValues>(
  error: unknown,
  setError: UseFormSetError<T>,
  fields: readonly Path<T>[],
): void {
  if (isApiError(error)) {
    let applied = false;
    for (const issue of error.fieldIssues) {
      const field = fields.find((f) => issue.path === f || issue.path.startsWith(`${f}.`));
      if (!field) continue;
      setError(field, { message: issue.message });
      applied = true;
    }
    if (applied) return;
  }
  setError('root.server', { message: describeError(error) });
}
/** What a comment box holds. */
export interface CommentFormValues {
  body: string;
}

/** Which comments the Feedback tab shows: those on the version being viewed, or on all. */
export type FeedbackFilter = 'version' | 'all';
import { Loader2Icon } from 'lucide-react';
import { Button } from '@/components/ui/button.tsx';
import { describeError } from '@/lib/api/api-error.ts';

/** A spinner that fills its container (a viewer, a list), unlike the full-page `PageLoading`. */
export function InlineLoading() {
  return (
    <div className="flex size-full items-center justify-center" aria-busy="true">
      <Loader2Icon className="size-6 animate-spin text-muted-foreground" aria-label="Loading" />
    </div>
  );
}

/** An error message with an optional retry, filling its container. */
export function InlineError({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  return (
    <div className="flex size-full flex-col items-center justify-center gap-3 p-6 text-center">
      <p role="alert" className="max-w-md text-sm text-muted-foreground">
        {typeof error === 'string' ? error : describeError(error)}
      </p>
      {onRetry ? (
        <Button variant="outline" size="sm" onClick={onRetry}>
          Try again
        </Button>
      ) : null}
    </div>
  );
}

