import type { CreateApiTokenRequest } from '@artifact-hub/shared';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  apiTokensQueryKey,
  createApiToken,
  fetchApiTokens,
  revokeApiToken,
} from './api-tokens-api.ts';

export function useApiTokens() {
  return useQuery({
    queryKey: apiTokensQueryKey,
    queryFn: ({ signal }) => fetchApiTokens(signal),
  });
}

export function useCreateApiToken() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateApiTokenRequest) => createApiToken(body),
    onSettled: () => queryClient.invalidateQueries({ queryKey: apiTokensQueryKey }),
  });
}

export function useRevokeApiToken() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (tokenId: string) => revokeApiToken(tokenId),
    onSettled: () => queryClient.invalidateQueries({ queryKey: apiTokensQueryKey }),
  });
}
EOF
cat > mcp-config.ts <<'EOF'
/** Name of the server in MCP client configs. */
const SERVER_NAME = 'artifact-hub';
/** Stands in for the token in the setup snippets until one is created. */
export const TOKEN_PLACEHOLDER = 'ah_your_token';

export function mcpEndpoint(origin: string): string {
  return `${origin}/mcp`;
}

/**
 * Claude Desktop config: `mcp-remote` bridges its stdio to our HTTP endpoint. The header is
 * passed through an env variable because some clients split arguments on spaces.
 */
export function claudeDesktopConfig(origin: string, token: string): string {
  const config = {
    mcpServers: {
      [SERVER_NAME]: {
        command: 'npx',
        args: [
          '-y',
          'mcp-remote',
          mcpEndpoint(origin),
          '--header',
          'Authorization:${ARTIFACT_HUB_AUTH}',
        ],
        env: { ARTIFACT_HUB_AUTH: `Bearer ${token}` },
      },
    },
  };
  return JSON.stringify(config, null, 2);
}

/** Claude Code talks HTTP directly. */
export function claudeCodeCommand(origin: string, token: string): string {
  return `claude mcp add --transport http ${SERVER_NAME} ${mcpEndpoint(origin)} --header "Authorization: Bearer ${token}"`;
}
EOF
cat > mcp-config.spec.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { claudeCodeCommand, claudeDesktopConfig } from './mcp-config.ts';

const ORIGIN = 'https://hub.example.com';
const TOKEN = 'ah_secret';

describe('claudeDesktopConfig', () => {
  it('points mcp-remote at the endpoint, with the token in its env', () => {
    expect(JSON.parse(claudeDesktopConfig(ORIGIN, TOKEN))).toEqual({
      mcpServers: {
        'artifact-hub': {
          command: 'npx',
          args: [
            '-y',
            'mcp-remote',
            'https://hub.example.com/mcp',
            '--header',
            'Authorization:${ARTIFACT_HUB_AUTH}',
          ],
          env: { ARTIFACT_HUB_AUTH: 'Bearer ah_secret' },
        },
      },
    });
  });
});

describe('claudeCodeCommand', () => {
  it('adds the HTTP server with the Bearer header', () => {
    expect(claudeCodeCommand(ORIGIN, TOKEN)).toBe(
      'claude mcp add --transport http artifact-hub https://hub.example.com/mcp --header "Authorization: Bearer ah_secret"',
    );
  });
});
EOF

