import { type CanActivate, type ExecutionContext, Inject, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ErrorCode } from '@artifact-hub/shared';
import type { Request, Response } from 'express';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import { AppError } from '../common/errors/app-error.js';
import { AUTH_SCHEMES_KEY, IS_PUBLIC_KEY } from './auth.decorators.js';
import type { AuthScheme, RequestAuthenticator } from './auth.types.js';

/** Every registered `RequestAuthenticator` (see `AuthModule.register`). */
export const REQUEST_AUTHENTICATORS = Symbol('REQUEST_AUTHENTICATORS');

const DEFAULT_SCHEMES: AuthScheme[] = ['session'];

/**
 * Global guard: every route requires credentials unless marked `@Public()`. A session by
 * default; `@Auth(...)` names others. Sets `req.auth` and adds the user to the request's log
 * lines. Fails closed: other transports, and schemes nobody registered, are errors.
 */
@Injectable()
export class AuthGuard implements CanActivate {
  private readonly authenticators: Map<AuthScheme, RequestAuthenticator>;

  constructor(
    private readonly reflector: Reflector,
    @Inject(REQUEST_AUTHENTICATORS) authenticators: RequestAuthenticator[],
    @InjectPinoLogger(AuthGuard.name) private readonly logger: PinoLogger,
  ) {
    this.authenticators = new Map();
    for (const authenticator of authenticators) {
      if (this.authenticators.has(authenticator.scheme)) {
        throw new Error(`Two authenticators for the '${authenticator.scheme}' scheme`);
      }
      this.authenticators.set(authenticator.scheme, authenticator);
    }
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // A new transport (websockets, microservices) must bring its own authentication.
    if (context.getType() !== 'http') {
      throw new Error(`AuthGuard only supports HTTP, not '${context.getType()}'`);
    }
    const targets = [context.getHandler(), context.getClass()];
    if (this.reflector.getAllAndOverride<boolean | undefined>(IS_PUBLIC_KEY, targets)) return true;
    const schemes =
      this.reflector.getAllAndOverride<AuthScheme[] | undefined>(AUTH_SCHEMES_KEY, targets) ??
      DEFAULT_SCHEMES;

    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();
    const accepted = schemes.map((scheme) => {
      const authenticator = this.authenticators.get(scheme);
      if (!authenticator) throw new Error(`No authenticator registered for '${scheme}'`);
      return authenticator;
    });
    for (const authenticator of accepted) {
      const auth = await authenticator.authenticate(req, res);
      if (!auth) continue;
      req.auth = auth;
      this.logger.assign({
        userId: auth.actor.userId,
        ...(auth.scheme === 'api_token' ? { tokenId: auth.apiTokenId } : {}),
      });
      return true;
    }
    throw new AppError(ErrorCode.UNAUTHENTICATED, accepted[0]!.missingCredentialsMessage);
  }
}
EOF
cat > auth/sessions/session-authenticator.service.ts <<'EOF'
import { Injectable } from '@nestjs/common';
import { ErrorCode } from '@artifact-hub/shared';
import type { Request, Response } from 'express';
import { AppError } from '../../common/errors/app-error.js';
import type { RequestAuth, RequestAuthenticator } from '../auth.types.js';
import { SessionCookieService } from './session-cookie.service.js';
import { SessionsService } from './sessions.service.js';

const LOG_IN_MESSAGE = 'Please log in.';

/** The session cookie of the web app. Re-sends the cookie when the session was extended. */
@Injectable()
export class SessionAuthenticatorService implements RequestAuthenticator {
  readonly scheme = 'session';
  readonly missingCredentialsMessage = LOG_IN_MESSAGE;

  constructor(
    private readonly sessions: SessionsService,
    private readonly cookie: SessionCookieService,
  ) {}

  async authenticate(req: Request, res: Response): Promise<RequestAuth | null> {
    const token = this.cookie.read(req);
    if (!token) return null;
    const resolved = await this.sessions.resolve(token);
    if (!resolved) {
      this.cookie.clear(res);
      throw new AppError(ErrorCode.UNAUTHENTICATED, LOG_IN_MESSAGE);
    }
    const { session, extended } = resolved;
    if (extended) this.cookie.set(res, token, session.expiresAt);
    return {
      scheme: 'session',
      actor: { userId: session.userId, via: 'web' },
      sessionId: session.id,
    };
  }
}
EOF
cat > api-tokens/api-token-authenticator.service.ts <<'EOF'
import { Injectable } from '@nestjs/common';
import { ErrorCode } from '@artifact-hub/shared';
import type { Request } from 'express';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import type { RequestAuth, RequestAuthenticator } from '../auth/auth.types.js';
import { AppError } from '../common/errors/app-error.js';
import { ApiTokensService } from './api-tokens.service.js';

const BEARER = /^Bearer\s+(\S+)\s*$/i;

/** `Authorization: Bearer ah_…`, for MCP clients and scripts. Authenticates as an MCP actor. */
@Injectable()
export class ApiTokenAuthenticatorService implements RequestAuthenticator {
  readonly scheme = 'api_token';
  readonly missingCredentialsMessage =
    'Send an API token as "Authorization: Bearer <token>". Create one in Settings → API tokens.';

  constructor(
    private readonly tokens: ApiTokensService,
    @InjectPinoLogger(ApiTokenAuthenticatorService.name) private readonly logger: PinoLogger,
  ) {}

  async authenticate(req: Request): Promise<RequestAuth | null> {
    const secret = BEARER.exec(req.get('authorization') ?? '')?.[1];
    if (secret === undefined) return null;
    const result = await this.tokens.check(secret);
    if (!result.ok) {
      this.logger.warn(
        { reason: result.reason, tokenId: result.tokenId, ip: req.ip },
        'API token rejected',
      );
      throw new AppError(
        ErrorCode.UNAUTHENTICATED,
        'This API token is not valid or was revoked. Create a new one in Settings → API tokens.',
      );
    }
    const { token } = result;
    return {
      scheme: 'api_token',
      actor: { userId: token.userId, via: 'mcp' },
      apiTokenId: token.id,
    };
  }
}
EOF
