            ...results.flatMap((r, i) => [
              `${(page - 1) * PAGE_SIZE + i + 1}. ${quoted(r.title)}: ${r.type ?? 'draft'} by ${quoted(r.owner)}${r.version ? `, v${r.version}` : ''}, updated ${r.updated_at.slice(0, 10)}`,
