        const { items, total } = await this.artifacts.list(actor, {
          ...SCOPE_FILTERS[scope](actor),
          search: query || undefined,
          mimeTypes: type ? ARTIFACT_TYPE_FILTERS[type] : undefined,
          tag,
          page,
          pageSize: PAGE_SIZE,
        });
        return this.foundArtifacts(items, { total, page, filtered: Boolean(query || type || tag) });
      },
    });
  }

  private getArtifact() {
    return defineTool({
      name: 'get_artifact',
      title: 'Get an artifact',
      description:
        'Show one artifact: its details, versions, who can see it, and how much feedback it has. Use it when the user asks about a specific artifact ("what\'s the status of the onboarding mockup?", "who can see it?", "what changed in v3?"), after find_artifacts, or to confirm an upload. For the comments themselves, use get_feedback.',
      inputSchema: {
        artifact: z
          .string()
          .describe("The artifact's id, or its page URL (…/artifacts/<id>, optionally ?v=N)."),
        version: z
          .number()
          .int()
          .min(1)
          .optional()
          .describe('A version number to show; the newest the user can see by default.'),
      },
      annotations: { readOnlyHint: true, openWorldHint: false },
      handler: async (actor, input) => {
        const ref = parseArtifactRef(input.artifact);
        const view = await this.artifacts.get(actor, ref.id);
        const [versions, threads, access] = await Promise.all([
          this.artifacts.listVersions(actor, ref.id),
          this.comments.list(actor, ref.id, { include: 'all' }),
          view.permissions.share ? this.sharing.getAccess(actor, ref.id) : null,
        ]);
        const versionNo = input.version ?? ref.versionNo ?? view.currentVersion?.versionNo;
        const version =
          versionNo === undefined ? null : versions.find((v) => v.versionNo === versionNo);
        if (version === undefined)
          throw new AppError(ErrorCode.NOT_FOUND, `Version ${versionNo} not found.`);
        return this.artifactDetails(actor, view, {
          version,
          versions,
          counts: countFeedback(threads),
          access,
        });
      },
    });
  }

  private foundArtifacts(
    items: ArtifactView[],
    { total, page, filtered }: { total: number; page: number; filtered: boolean },
  ): ToolOutput {
    const hasMore = page * PAGE_SIZE < total;
    const results = items.map((view) => {
      const { artifact, currentVersion } = view;
      const description =
        artifact.description.length > DESCRIPTION_PREVIEW_LENGTH
          ? `${artifact.description.slice(0, DESCRIPTION_PREVIEW_LENGTH)}…`
          : artifact.description;
      return {
        id: artifact.id,
        title: artifact.title,
        description,
        type: currentVersion ? typeName(currentVersion.mimeType) : null,
        tags: artifact.tags,
        owner: artifact.owner.displayName,
        version: currentVersion?.versionNo ?? null,
        updated_at: artifact.updatedAt.toISOString(),
        url: artifactPageUrl(this.env.APP_BASE_URL, artifact.id),
      };
    });

    const nextActions =
      total === 0
        ? [
            filtered
              ? 'Try fewer or different keywords, or drop the type and tag filters.'
              : 'Nothing to show yet: the user has no artifacts and none are shared with them.',
          ]
        : [
            'Call get_artifact with an id for versions, access and feedback counts.',
            'Call get_feedback with an id to read the comments.',
            ...(hasMore ? [`Call find_artifacts with page: ${page + 1} for more.`] : []),
          ];

    const lines =
      total === 0
        ? ['No artifacts match.']
        : [
            `Found ${total} ${total === 1 ? 'artifact' : 'artifacts'}${total > PAGE_SIZE ? `, showing ${(page - 1) * PAGE_SIZE + 1}–${(page - 1) * PAGE_SIZE + results.length}` : ''}.`,
            UNTRUSTED_NOTE,
            '',
            ...results.flatMap((r, i) => [
              `${(page - 1) * PAGE_SIZE + i + 1}. ${quoted(r.title)}: ${r.type ?? 'draft'} by ${quoted(r.owner)}${r.version ? `, v${r.version}` : ''}, updated ${r.updated_at.slice(0, 10)}`,
              ...(r.tags.length > 0 ? [`   Tags: ${r.tags.map(quoted).join(', ')}`] : []),
              ...(r.description ? [`   Description: ${quoted(r.description)}`] : []),
              `   id: ${r.id}`,
              `   ${r.url}`,
            ]),
          ];
    return {
      text: [...lines, '', ...nextActions].join('\n'),
      data: {
        total,
        page,
        page_size: PAGE_SIZE,
        has_more: hasMore,
        items: results,
        next_actions: nextActions,
      },
    };
  }

  private artifactDetails(
    actor: Actor,
    view: ArtifactView,
    details: {
      version: ArtifactVersion | null;
      versions: ArtifactVersion[];
      counts: FeedbackCounts;
      access: ArtifactAccess | null;
    },
  ): ToolOutput {
    const { artifact, permissions } = view;
    const { version, versions, counts, access } = details;
    const base = this.env.APP_BASE_URL;
    const url = artifactPageUrl(base, artifact.id);
    const youCan = [
      'view',
      ...Object.entries(permissions)
        .filter(([, can]) => can)
        .map(([what]) => what),
    ];
    const isOwner = artifact.ownerId === actor.userId;
    const onVersion = version
      ? counts.byVersion.find((c) => c.versionNo === version.versionNo)
      : undefined;

    const versionData = version && {
      number: version.versionNo,
      type: typeName(version.mimeType),
      size_bytes: version.sizeBytes,
      filename: version.originalFilename,
      change_note: version.changeNote,
      created_at: version.createdAt.toISOString(),
      url: artifactPageUrl(base, artifact.id, version.versionNo),
    };
    const nextActions = [
      ...(counts.open + counts.resolved > 0 ? ['Call get_feedback to read the comments.'] : []),
      ...(versions.length > 1 && version
        ? ['Call get_artifact with another version number to see that version.']
        : []),
    ];

    const lines = [
      `${quoted(artifact.title)} by ${quoted(artifact.owner.displayName)}${isOwner ? ' (you)' : ''}`,
      url,
      UNTRUSTED_NOTE,
      ...(artifact.description ? ['Description:', untrusted(artifact.description)] : []),
      `Tags: ${artifact.tags.length > 0 ? artifact.tags.map(quoted).join(', ') : 'none'}`,
      `Created ${artifact.createdAt.toISOString().slice(0, 10)}, updated ${artifact.updatedAt.toISOString().slice(0, 10)}.`,
      '',
      version
        ? `Version ${version.versionNo} of ${view.latestVersionNo}: ${typeName(version.mimeType)}, ${version.sizeBytes} bytes, ${version.createdAt.toISOString().slice(0, 10)}${version.changeNote ? `, change note: ${quoted(version.changeNote)}` : ''}`
        : 'Draft: waiting for its first upload.',
      ...(versionData ? [versionData.url] : []),
      ...(versions.length > 1
        ? [
            `Versions you can see: ${versions
              .slice(0, VERSIONS_SHOWN)
              .map((v) => `v${v.versionNo} (${v.createdAt.toISOString().slice(0, 10)})`)
              .join(', ')}${versions.length > VERSIONS_SHOWN ? ', …' : ''}`,
          ]
        : []),
      '',
      `Feedback: ${describeCounts(counts)}${version && versions.length > 1 ? `; on v${version.versionNo}: ${describeCounts(onVersion ?? { open: 0, resolved: 0 })}` : ''}.`,
      access ? describeAccess(access) : `Access: you can ${youCan.join(', ')}.`,
      ...(nextActions.length > 0 ? ['', ...nextActions] : []),
    ];

    return {
      text: lines.join('\n'),
      data: {
        id: artifact.id,
        title: artifact.title,
        description: artifact.description,
        tags: artifact.tags,
        owner: artifact.owner.displayName,
        status: artifact.status,
        url,
        created_at: artifact.createdAt.toISOString(),
        updated_at: artifact.updatedAt.toISOString(),
        your_permissions: youCan,
        latest_version: view.latestVersionNo,
        version: versionData,
        versions: versions.slice(0, VERSIONS_SHOWN).map((v) => ({
          number: v.versionNo,
          created_at: v.createdAt.toISOString(),
          change_note: v.changeNote,
        })),
        feedback: {
          open: counts.open,
          resolved: counts.resolved,
          by_version: counts.byVersion.map(({ versionNo, open, resolved }) => ({
            version: versionNo,
            open,
            resolved,
          })),
        },
        access: access && accessData(access),
        next_actions: nextActions,
      },
    };
  }
}

function versionChoice(pinnedVersionNo: number | null): string {
  return pinnedVersionNo === null ? 'all versions' : `only v${pinnedVersionNo}`;
}

/** Who can see it, for its owner. The link's URL is left out: share_artifact hands it out. */
function describeAccess(access: ArtifactAccess): string {
  const lines = ['Access:'];
  if (access.company.enabled) {
    lines.push(`- Everyone at the company (${versionChoice(access.company.pinnedVersionNo)})`);
  }
  for (const person of access.people) {
    lines.push(
      `- ${quoted(person.user.displayName)}: can ${person.permission} (${versionChoice(person.pinnedVersionNo)})`,
    );
  }
  if (access.link) {
    const expiry = access.link.expiresAt
      ? `${Date.parse(access.link.expiresAt) <= Date.now() ? 'expired' : 'expires'} ${access.link.expiresAt.slice(0, 10)}`
      : 'never expires';
    lines.push(
      `- Anyone with the link, no sign-in (${versionChoice(access.link.pinnedVersionNo)}, ${expiry})`,
    );
  }
  return lines.length === 1 ? 'Access: only you.' : lines.join('\n');
}

function accessData(access: ArtifactAccess) {
  return {
    company: access.company.enabled ? { version: access.company.pinnedVersionNo } : null,
    people: access.people.map((person) => ({
      name: person.user.displayName,
      email: person.user.email,
      permission: person.permission,
      version: person.pinnedVersionNo,
    })),
    link: access.link && {
      version: access.link.pinnedVersionNo,
      expires_at: access.link.expiresAt,
    },
  };
}

