        const versionNo = input.version ?? ref.versionNo;
        const view = await this.artifacts.get(actor, ref.id);
        // Everything once: the counts cover resolved threads even when only open ones are shown.
        const all = await this.comments.list(actor, ref.id, { versionNo, include: 'all' });
        const threads =
          input.include === 'open' ? all.filter((t) => t.comment.resolvedAt === null) : all;
        return this.feedback(view, {
          versionNo,
          include: input.include,
          threads,
          counts: countFeedback(all),
        });
      },
    });
  }

  private feedback(
    view: ArtifactView,
    {
      versionNo,
      include,
      threads,
      counts,
    }: {
      versionNo: number | undefined;
      include: (typeof COMMENT_INCLUDE_OPTIONS)[number];
      threads: CommentThreadView[];
      counts: FeedbackCounts;
    },
  ): ToolOutput {
    const { artifact } = view;
    const base = this.env.APP_BASE_URL;
    const url = artifactPageUrl(base, artifact.id, versionNo);
    const shown = threads.slice(0, MAX_THREADS);
    const omitted = threads.length - shown.length;
    const scope = `${versionNo === undefined ? 'all versions you can see' : `v${versionNo}`}, ${include === 'open' ? 'open threads' : 'open and resolved threads'}`;

    const nextActions = [
      ...(omitted > 0
        ? [
            `${omitted} more ${omitted === 1 ? 'thread is' : 'threads are'} not shown: narrow with version${include === 'all' ? " or include: 'open'" : ''}, or point the user to the URL.`,
          ]
        : []),
      ...(include === 'open' && counts.resolved > 0
        ? ["Call get_feedback with include: 'all' to read the resolved threads too."]
        : []),
    ];

    const lines = [
      `Feedback on ${quoted(artifact.title)} (${scope}): ${describeCounts(counts)}${versionNo === undefined && counts.byVersion.length > 1 ? ` (${counts.byVersion.map((c) => `v${c.versionNo}: ${describeCounts(c)}`).join('; ')})` : ''}.`,
      url,
      UNTRUSTED_NOTE,
      '',
      ...(shown.length === 0
        ? [include === 'open' ? 'No open threads.' : 'No comments yet.']
        : shown.flatMap((thread, i) => [...(i > 0 ? [''] : []), ...describeThread(thread, i + 1)])),
      ...(nextActions.length > 0 ? ['', ...nextActions] : []),
    ];

    return {
      text: lines.join('\n'),
      data: {
        artifact: {
          id: artifact.id,
          title: artifact.title,
          url: artifactPageUrl(base, artifact.id),
        },
        version: versionNo ?? null,
        include,
        counts: {
          open: counts.open,
          resolved: counts.resolved,
          by_version: counts.byVersion.map(({ versionNo: version, open, resolved }) => ({
            version,
            open,
            resolved,
          })),
        },
        note: UNTRUSTED_NOTE,
        threads: shown.map((thread) => ({
          ...commentData(thread),
          version: thread.comment.version.versionNo,
          resolved: thread.comment.resolvedAt !== null,
          url: artifactPageUrl(base, artifact.id, thread.comment.version.versionNo),
          replies: thread.replies.slice(0, MAX_REPLIES).map(commentData),
          replies_not_shown: Math.max(0, thread.replies.length - MAX_REPLIES),
        })),
        threads_not_shown: omitted,
        next_actions: nextActions,
      },
    };
  }
}

function commentData({ comment }: CommentView) {
  return {
    id: comment.id,
    author: comment.author.displayName,
    body: comment.body,
    created_at: comment.createdAt.toISOString(),
    edited: comment.editedAt !== null,
  };
}

function describeThread(thread: CommentThreadView, number: number): string[] {
  const { comment, replies } = thread;
  const hidden = replies.length - MAX_REPLIES;
  return [
    `${number}. ${describeComment(thread)} on v${comment.version.versionNo}, ${comment.resolvedAt ? 'resolved' : 'open'} (comment id: ${comment.id})`,
    untrusted(comment.body),
    ...replies
      .slice(0, MAX_REPLIES)
      .flatMap((reply) => [`   Reply: ${describeComment(reply)}`, untrusted(reply.comment.body)]),
    ...(hidden > 0 ? [`   (${hidden} more ${hidden === 1 ? 'reply' : 'replies'} not shown)`] : []),
  ];
}

function describeComment({ comment }: CommentView): string {
  return `${quoted(comment.author.displayName)}, ${comment.createdAt.toISOString().slice(0, 16).replace('T', ' ')} UTC${comment.editedAt ? ', edited' : ''}`;
}

