import type { Readable } from 'node:stream';
import type { ArtifactMimeType, TextFormat } from '@artifact-hub/shared';

/** What the client tells us about the content. Used only to choose among text formats. */
export interface ContentHint {
  /** Original filename; only its extension is read. */
  filename?: string;
  /** Explicit text format (MCP inline content). Takes precedence over the filename. */
  textFormat?: TextFormat;
}

export interface InspectedContent {
  mimeType: ArtifactMimeType;
  /**
   * The full content, starting with the bytes read for detection. Errors with
   * `ARTIFACT_TOO_LARGE` past the size limit, and with `UNSUPPORTED_TYPE` if text content
   * turns out not to be UTF-8 further in.
   */
  body: Readable;
}
    @InjectStorage() private readonly storage: StorageDriver,
    private readonly access: AccessPolicyService,
    private readonly grants: AccessGrantsService,
    @InjectPinoLogger(ArtifactsService.name) private readonly logger: PinoLogger,
  ) {}

  /**
   * Publishes a new artifact with `content` as version 1 (plan §6): detect the type, store the
   * blob, then insert the rows in one transaction. The blob is deleted if the insert fails.
   */
  async create(
    actor: Actor,
    metadata: CreateArtifactMetadata,
    content: NewContent,
  ): Promise<ArtifactView> {
    const artifactId = randomUUID();
    const log = { userId: actor.userId, artifactId, via: actor.via };
    this.logger.info(log, 'Publish received');

    const stored = await this.storeContent(artifactId, 1, content, log);
    try {
      await this.dataSource.transaction(async (manager) => {
        // Inserted as a draft first: a published artifact must point at a version.
        await manager.insert(Artifact, {
          id: artifactId,
          ownerId: actor.userId,
          title: metadata.title,
          description: metadata.description,
          tags: metadata.tags,
          visibility: metadata.visibility,
          status: 'draft',
          metadataSource: 'user',
          latestVersionNo: 0,
        });
        await this.insertVersion(manager, actor, artifactId, 1, stored, null);
      });
    } catch (error) {
      await this.deleteBlobQuietly(stored.storageKey, log);
      throw error;
    }
    this.logger.info({ ...log, versionNo: 1 }, 'Version committed');

    return this.get(actor, artifactId);
  }

  /**
   * Adds `content` as the next version and makes it current. Only the owner may. The artifact
   * row is locked while the version is numbered; if another version was committed since the
   * number was picked for the blob key, this fails with `CONFLICT` and the client can retry.
   */
  async addVersion(
    actor: Actor,
    id: string,
    metadata: CreateVersionMetadata,
    content: NewContent,
  ): Promise<ArtifactView> {
    const { artifact } = await this.getForAction(actor, id, 'edit');
    const versionNo = artifact.latestVersionNo + 1;
    const log = { userId: actor.userId, artifactId: artifact.id, via: actor.via };
    this.logger.info({ ...log, versionNo }, 'New version received');

    const stored = await this.storeContent(artifact.id, versionNo, content, log);
    try {
      await this.dataSource.transaction(async (manager) => {
        const locked = await manager.findOne(Artifact, {
          where: { id: artifact.id, deletedAt: IsNull() },
          lock: { mode: 'pessimistic_write' },
        });
        if (!locked) throw new AppError(ErrorCode.NOT_FOUND, ARTIFACT_NOT_FOUND_MESSAGE);
        if (locked.latestVersionNo !== versionNo - 1) {
          throw new AppError(
            ErrorCode.CONFLICT,
            'Another version was published at the same time. Try again.',
          );
        }
        await this.insertVersion(
          manager,
          actor,
          artifact.id,
          versionNo,
          stored,
          metadata.changeNote || null,
        );
      });
    } catch (error) {
      await this.deleteBlobQuietly(stored.storageKey, log);
      throw error;
    }
    this.logger.info({ ...log, versionNo }, 'Version committed');

    return this.get(actor, artifact.id);
  }

  );

/** Metadata sent with a new artifact (the `metadata` part of the multipart upload). */
export const createArtifactRequestSchema = z.object({
  title: artifactTitleSchema,
  description: artifactDescriptionSchema.default(''),
  tags: artifactTagsSchema.default([]),
  visibility: artifactVisibilitySchema.default('private'),
});

export type CreateArtifactRequest = z.input<typeof createArtifactRequestSchema>;
export type CreateArtifactMetadata = z.output<typeof createArtifactRequestSchema>;

/**
 * Body of `PATCH /api/artifacts/:id`: only the fields to change. Never creates a version.
 * Access (including visibility) is changed through `/api/artifacts/:id/access`.
 */
export const updateArtifactRequestSchema = z
  .strictObject({
    title: artifactTitleSchema,
    description: artifactDescriptionSchema,
    tags: artifactTagsSchema,
  })
  .partial()
  .refine((update) => Object.values(update).some((value) => value !== undefined), {
    message: 'Send at least one field to change.',
  });

export type UpdateArtifactRequest = z.input<typeof updateArtifactRequestSchema>;
export type UpdateArtifactMetadata = z.output<typeof updateArtifactRequestSchema>;

export const VERSION_CHANGE_NOTE_MAX_LENGTH = 500;

/** Details sent with a new version (the `metadata` part of the multipart upload). */
export const createVersionRequestSchema = z.object({
  /** What changed. Blank means none. */
  changeNote: z
    .string()
    .trim()
    .max(
      VERSION_CHANGE_NOTE_MAX_LENGTH,
      `Keep the change note to ${VERSION_CHANGE_NOTE_MAX_LENGTH} characters.`,
    )
    .default(''),
});

