import { Readable } from 'node:stream';
import { ErrorCode, TEXT_FORMAT_MIME_TYPES, type TextFormat } from '@artifact-hub/shared';
import type { ArtifactVersion } from '../../artifacts/artifact-version.entity.js';
import type { NewContent } from '../../artifacts/artifacts.types.js';
import { AppError } from '../../common/errors/app-error.js';

/** Text sent inline by an MCP client, for the upload pipeline (which checks size and type). */
export function inlineContent(content: string, textFormat: TextFormat): NewContent {
  return { stream: Readable.from([Buffer.from(content, 'utf8')]), textFormat };
}

/**
 * The format of new content: as given, or the current version's when it is a text format, so
 * a revision of an HTML page needn't say "html" again.
 */
export function formatForRevision(
  given: TextFormat | undefined,
  current: ArtifactVersion | null,
): TextFormat {
  if (given) return given;
  const formats = Object.entries(TEXT_FORMAT_MIME_TYPES) as [TextFormat, string][];
  const same = formats.find(([, mimeType]) => mimeType === current?.mimeType)?.[0];
  if (same) return same;
  throw new AppError(
    ErrorCode.VALIDATION_FAILED,
    'Say which format the new content is in: html, svg or markdown.',
  );
}
EOF
cat > inline-content.spec.ts <<'EOF'
import type { ArtifactVersion } from '../../artifacts/artifact-version.entity.js';
import { formatForRevision, inlineContent } from './inline-content.js';

const version = (mimeType: string) => ({ mimeType }) as ArtifactVersion;

describe('inlineContent', () => {
  it('streams the text as UTF-8, with its format', async () => {
    const { stream, textFormat } = inlineContent('<h1>Héllo</h1>', 'html');
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(chunk as Buffer);
    expect(Buffer.concat(chunks).toString('utf8')).toBe('<h1>Héllo</h1>');
    expect(textFormat).toBe('html');
  });
});

describe('formatForRevision', () => {
  it('takes the given format', () => {
    expect(formatForRevision('svg', version('text/html'))).toBe('svg');
  });

  it.each([
    ['text/html', 'html'],
    ['image/svg+xml', 'svg'],
    ['text/markdown', 'markdown'],
  ])("keeps the current version's text format (%s)", (mimeType, format) => {
    expect(formatForRevision(undefined, version(mimeType))).toBe(format);
  });

  it('asks for the format when the current version is binary, or there is none', () => {
    expect(() => formatForRevision(undefined, version('image/png'))).toThrow(/Say which format/);
    expect(() => formatForRevision(undefined, null)).toThrow(/Say which format/);
  });
});
EOF

