interface ToolData extends Record<string, unknown> {
  items: { id: string }[];
  versions: { number: number }[];
  threads: { resolved: boolean }[];
  next_actions: string[];
}

interface ToolResult {
  text: string;
  data: ToolData;
  isError: boolean;
}

